# A kick on every beat, a snare on two and four, a hat on every eighth whose
# velocity the seed and one param decide (ADR 0024 §3's worked example).
for b in range(4):
    note(36, beat(b), beat(1) // 2, 100)
    if b % 2 == 1:
        note(38, beat(b), beat(1) // 2, 110)
    for h in range(2):
        note(42, beat(b) + h * (beat(1) // 2), beat(1) // 4, 60 + rng.randrange(0, int(params["spread"])))
